-- 《工地风云》精选作品创作过程：修复画布媒体地址（v2，修正上一版的文字二次编码）
-- 作品：featured-ba083866657a41b3（工地风云，线上 comfyui.zlyun168.com）
-- 上一版问题：v1 文件的负载取自被按 Latin-1 解码的接口响应，写库后中文变成「å·¥å°é£äº」这类乱码。
--             本版把该负载还原为正确 UTF-8，媒体地址改写结果与 v1 完全一致。
-- 内容：canvas 节点里 /api/jobs/<job>/generations/<item>/outputs/0/download 改写为七牛长效地址
--       https://img.zlyun168.com/zly-ai-video-studio/minimax_h3/20261105/183547_02c7469d47b1b89b.mp4
--       其余字段（标题/简介/封面/剧集/资产/画布结构/提示词）保持原样。
-- 执行前建议备份：CREATE TABLE bak_ai_featured_works_20261109_v2 AS SELECT * FROM ai_featured_works WHERE id = 'featured-ba083866657a41b3';
-- 只做数据修复，不建表不改结构；重复执行结果相同（幂等）。
-- 校验用 HEX() 比较，避免客户端字符集影响检查结果。

SET NAMES utf8mb4;

START TRANSACTION;

UPDATE ai_featured_works
SET snapshot_json = CONVERT( USING utf8mb4),
    updated_at = NOW()
WHERE id = 'featured-ba083866657a41b3';

COMMIT;

SELECT id,
       title,
       updated_at,
       CHAR_LENGTH(snapshot_json) AS snapshot_chars,
       CASE WHEN snapshot_json LIKE '%/api/jobs/%' THEN 'STILL_BROKEN' ELSE 'OK' END AS media_check,
       CASE WHEN HEX(snapshot_json) LIKE '%E5B7A5E59CB0E9A38EE4BA91%' THEN 'OK' ELSE 'TEXT_BROKEN' END AS text_check,
       CASE WHEN snapshot_json LIKE '%183547_02c7469d47b1b89b.mp4%' THEN 'OK' ELSE 'CDN_MISSING' END AS cdn_check
FROM ai_featured_works
WHERE id = 'featured-ba083866657a41b3';
